import com.mavric.health.shared.*;
import com.mavric.health.billing.domain.Requests.Post;
import com.mavric.health.persistence.sqlserver.SqlServerIdentityStoreTest.ModelTransactionManager;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
/** Offline contract/model tests; no ledger, refund lock, race or engine execution evidence. */
public class SqlServerFinanceStoreTest {
 public static final String ACTOR="aa000000-0000-4000-8000-000000000001",TENANT="bb000000-0000-4000-8000-000000000001",PATIENT="cc000000-0000-4000-8000-000000000001",MOVEMENT="dd000000-0000-4000-8000-000000000001",OTHER="ee000000-0000-4000-8000-000000000001",DATE="2026-11-05T00:00:00.123456Z",KEY="synthetic-key-001";
 public static Post input(){return new Post(PATIENT,"CHARGE",125L,"Synthetic \u00e1\u4e2d\ud83e\uddb7",null);}
 public static Map<String,Object> movement(){var r=new LinkedHashMap<String,Object>();r.put("id",MOVEMENT);r.put("tenantId",TENANT);r.put("patientId",PATIENT);r.put("kind","CHARGE");r.put("amountMinor",125L);r.put("currency","PEN");r.put("title",input().title());r.put("parentId",null);r.put("actorId",ACTOR);r.put("requestKey",KEY);r.put("requestHash",Checks.hash("synthetic-json"));r.put("createdAt",DATE);return r;}
 public static class Fixture {
  public final SqlServerExecutor executor=mock(SqlServerExecutor.class);public final ModelTransactionManager manager=new ModelTransactionManager();public final ObjectMapper mapper=new ObjectMapper();public final SqlServerFinanceStore store=new SqlServerFinanceStore(executor,manager,mapper);public final MockHttpServletRequest request=new MockHttpServletRequest("POST","/api/finance");public Actor actor;public Number balance=new BigDecimal("0");public boolean replay;public final List<SqlServerProcedure> calls=new ArrayList<>();public final List<List<Object>> args=new ArrayList<>();public final Deque<SqlServerExecutor.Result> results=new ArrayDeque<>();public final List<Map<String,Object>> listing=new ArrayList<>();
  public Fixture(){actor("CAJ");when(executor.execute(any(),any(),any(Object[].class))).thenAnswer(inv->{assertTrue(TransactionSynchronizationManager.isActualTransactionActive());var c=inv.<SqlServerContext>getArgument(1);assertEquals(SqlServerContext.Scope.REQUEST,c.scope());assertEquals(ACTOR,c.actorId());assertEquals(TENANT,c.tenantId());assertEquals("a".repeat(64),c.tokenHash());var sp=inv.<SqlServerProcedure>getArgument(0);Object[] a=((Object[])inv.getRawArguments()[2]).clone();calls.add(sp);args.add(Arrays.asList(a));manager.events.add("sp:"+sp.name());if(!results.isEmpty())return results.removeFirst();if(sp==SqlServerProcedure.FINANCE_BALANCE)return result(List.of(Map.of("balanceMinor",balance,"currency","PEN")));if(sp==SqlServerProcedure.FINANCE_MOVEMENTS)return result(listing);var row=movement();var body=mapper.readValue((String)a[1],Map.class);row.putAll(body);row.put("amountMinor",((Number)body.get("amountMinor")).longValue());row.put("id",replay?MOVEMENT:a[0]);row.put("actorId",replay?OTHER:ACTOR);row.put("requestKey",a[2]);row.put("requestHash",a[3]);return result(List.of(row));});}
  public void actor(String role){actor=new Actor(ACTOR,"Synthetic","synthetic@example.test",TENANT,List.of(role),"a".repeat(64));request.setAttribute("health.actor",actor);request.setAttribute("health.tenant",new TenantRef(TENANT,"Synthetic","clinic","CLINIC","HUMAN","ACTIVE",List.of("FINANCE")));request.setAttribute("health.requestId",OTHER);}
 }
 public static SqlServerExecutor.Result result(List<Map<String,Object>> rows){return new SqlServerExecutor.Result(List.of(rows),List.of());}
 final Fixture f=new Fixture();
 @AfterEach void clean(){TraceContext.REQUEST.remove();SecurityContextHolder.clearContext();TransactionSynchronizationManager.clear();}
 static void safe(Runnable r){var e=assertThrows(ApiException.class,r::run);assertEquals(500,e.status);assertEquals("DATABASE_ERROR",e.code);assertNull(e.getCause());assertFalse(e.toString().contains("canary"));}
 @Test void decimal38NegativeZeroAndBeyondLongArePreservedExactlyAsNumber(){for(Number value:List.<Number>of(new BigDecimal("99999999999999999999999999999999999999"),new BigDecimal("-99999999999999999999999999999999999999"),BigDecimal.ZERO,new BigInteger("92233720368547758081234"),Long.MIN_VALUE,0)){f.balance=value;var out=f.store.balance(f.request,PATIENT);assertSame(value,out.get("balanceMinor"));assertEquals("PEN",out.get("currency"));assertThrows(UnsupportedOperationException.class,out::clear);}assertEquals(Collections.nCopies(6,SqlServerProcedure.FINANCE_BALANCE),f.calls);assertEquals(List.of(PATIENT),f.args.getFirst());}
 @Test void invalidDecimalFractionFloatNaNRangeCurrencyAndBalanceShapeFail(){for(Object value:List.of("0",0.0,Double.NaN,new BigDecimal("0.1"),BigInteger.TEN.pow(38),new java.util.concurrent.atomic.AtomicLong(1))){f.results.add(result(List.of(Map.of("balanceMinor",value,"currency","PEN"))));safe(()->f.store.balance(f.request,PATIENT));}for(String currency:List.of("USD","pen","PEN ")){f.results.add(result(List.of(Map.of("balanceMinor",BigDecimal.ZERO,"currency",currency))));safe(()->f.store.balance(f.request,PATIENT));}f.results.add(result(List.of()));safe(()->f.store.balance(f.request,PATIENT));f.results.add(result(List.of(Map.of("balanceMinor",BigDecimal.ZERO))));safe(()->f.store.balance(f.request,PATIENT));}
 @Test void movementsOneSpNoBalancePreflightTwelveFieldsOrderAndImmutable(){var row=movement();row.put("passwordHash","private-canary");row.put("amountMinor",Long.MAX_VALUE);f.listing.add(row);var out=f.store.movements(f.request,PATIENT);assertEquals(12,out.getFirst().size());assertEquals(Long.MAX_VALUE,out.getFirst().get("amountMinor"));assertNull(out.getFirst().get("parentId"));assertFalse(out.toString().contains("canary"));assertThrows(UnsupportedOperationException.class,out::clear);assertThrows(UnsupportedOperationException.class,out.getFirst()::clear);assertEquals(List.of(SqlServerProcedure.FINANCE_MOVEMENTS),f.calls);assertEquals(List.of(PATIENT),f.args.getFirst());}
 @Test void movementsEmpty200OrderAndExactResultsetLimits(){assertTrue(f.store.movements(f.request,PATIENT).isEmpty());for(int i=0;i<200;i++){var row=movement();row.put("id",UUID.nameUUIDFromBytes(("synthetic"+i).getBytes(java.nio.charset.StandardCharsets.UTF_8)).toString());row.put("createdAt",java.time.Instant.parse(DATE).minusSeconds(i).toString());f.listing.add(row);}var out=f.store.movements(f.request,PATIENT);assertEquals(f.listing.getLast(),out.getLast());f.listing.add(movement());safe(()->f.store.movements(f.request,PATIENT));for(var bad:List.of(new SqlServerExecutor.Result(List.of(),List.of()),new SqlServerExecutor.Result(List.of(List.of(),List.of()),List.of()))){f.results.add(bad);safe(()->f.store.movements(f.request,PATIENT));}}
 @Test void postExactConfiguredSerializerUtf8HashBindsAndReplayOtherIdActor(){var mapper=tools.jackson.databind.json.JsonMapper.builder().enable(tools.jackson.databind.SerializationFeature.INDENT_OUTPUT).build();var store=new SqlServerFinanceStore(f.executor,f.manager,mapper);var p=input();f.replay=true;var row=store.post(f.request,p,KEY);assertEquals(MOVEMENT,row.get("id"));assertEquals(OTHER,row.get("actorId"));var args=f.args.getFirst();assertEquals(4,args.size());assertNotEquals(MOVEMENT,args.getFirst());assertDoesNotThrow(()->UUID.fromString((String)args.getFirst()));var legacy=new Sql(mock(org.springframework.jdbc.core.JdbcTemplate.class),mapper);assertEquals(legacy.json(p),args.get(1));assertEquals(Checks.hash(legacy.json(p)),args.get(3));assertEquals(KEY,args.get(2));assertEquals(List.of(SqlServerProcedure.FINANCE_POST),f.calls);assertEquals(12,row.size());assertEquals(List.of("begin:0","sp:FINANCE_POST","commit"),f.manager.events);}
 @Test void postAllKindsAndDifferentKeysHaveNoJavaLedgerQueries(){for(String kind:List.of("CHARGE","PAYMENT","REFUND")){var p=new Post(PATIENT,kind,1,"Synthetic",kind.equals("REFUND")?OTHER:null);assertEquals(kind,f.store.post(f.request,p,"synthetic-"+kind).get("kind"));assertEquals("synthetic-"+kind,f.args.getLast().get(2));}assertEquals(Collections.nCopies(3,SqlServerProcedure.FINANCE_POST),f.calls);}
 @Test void postInvalidInputsKeysAndIdsBeforeExecutor(){var p=input();var bad=new ArrayList<Post>();bad.add(null);bad.add(new Post("bad",p.kind(),p.amountMinor(),p.title(),null));bad.add(new Post(PATIENT,p.kind(),p.amountMinor(),p.title(),"bad"));for(String kind:Arrays.asList(null,"charge","bad"))bad.add(new Post(PATIENT,kind,1,"Synthetic",null));for(long amount:new long[]{0,-1,1000000000001L})bad.add(new Post(PATIENT,"CHARGE",amount,"Synthetic",null));for(String title:Arrays.asList(null," ","x".repeat(201)))bad.add(new Post(PATIENT,"CHARGE",1,title,null));for(Post input:bad)assertEquals(400,assertThrows(ApiException.class,()->f.store.post(f.request,input,KEY)).status);for(String key:Arrays.asList(null,"short","bad key space","x".repeat(101)))assertEquals(400,assertThrows(ApiException.class,()->f.store.post(f.request,p,key)).status);assertEquals(400,assertThrows(ApiException.class,()->f.store.balance(f.request,"bad")).status);assertEquals(400,assertThrows(ApiException.class,()->f.store.movements(f.request,"bad")).status);verifyNoInteractions(f.executor);}
 @Test void everyMovementFieldAndTenantPatientTypesDateAreValidated(){for(String key:movement().keySet()){var bad=movement();bad.remove(key);f.results.add(result(List.of(bad)));safe(()->f.store.movements(f.request,PATIENT));if(key.equals("parentId"))continue;bad=movement();bad.put(key,null);f.results.add(result(List.of(bad)));safe(()->f.store.movements(f.request,PATIENT));}for(var change:List.of(Map.entry("tenantId",OTHER),Map.entry("patientId",OTHER),Map.entry("id","bad"),Map.entry("actorId","bad"),Map.entry("parentId","bad"),Map.entry("kind","bad"),Map.entry("amountMinor",1),Map.entry("amountMinor",0L),Map.entry("currency","TOOLONG"),Map.entry("title",false),Map.entry("requestKey","bad key"),Map.entry("requestHash","bad"),Map.entry("createdAt","2026-11-05T00:00:00.123456789Z"))){var bad=movement();bad.put(change.getKey(),change.getValue());f.results.add(result(List.of(bad)));safe(()->f.store.movements(f.request,PATIENT));assertEquals("rollback",f.manager.events.getLast());}}
 @Test void postMismatchedPatientKeyHashOrMalformedCardinalityAreNotSuccess(){for(var change:List.of(Map.entry("patientId",OTHER),Map.entry("requestKey","another-key-001"),Map.entry("requestHash","f".repeat(64)))){var row=movement();row.put("requestHash",Checks.hash(f.mapper.writeValueAsString(input())));row.put(change.getKey(),change.getValue());f.results.add(result(List.of(row)));safe(()->f.store.post(f.request,input(),KEY));}f.results.add(result(List.of()));safe(()->f.store.post(f.request,input(),KEY));f.results.add(result(List.of(movement(),movement())));safe(()->f.store.post(f.request,input(),KEY));}
 @Test void contextRolesFinanceWriteStatusAndForeignActorGuards(){for(String role:List.of("CAJ","AUD")){f.actor(role);f.request.setAttribute("health.tenant",new TenantRef(TENANT,"Synthetic","clinic","CLINIC","HUMAN","SUSPENDED",List.of("FINANCE")));f.store.balance(f.request,PATIENT);}f.actor("AUD");assertEquals(403,assertThrows(ApiException.class,()->f.store.post(f.request,input(),KEY)).status);for(String role:List.of("ADM","PRO","REC","PAC","RES","SAD","SOP")){f.actor(role);assertEquals(403,assertThrows(ApiException.class,()->f.store.balance(f.request,PATIENT)).status);}f.actor("CAJ");f.request.setAttribute("health.tenant",new TenantRef(TENANT,"Synthetic","clinic","CLINIC","HUMAN","SUSPENDED",List.of()));assertEquals("SUSPENDED",assertThrows(ApiException.class,()->f.store.post(f.request,input(),KEY)).code);f.request.setAttribute("health.tenant",new TenantRef(TENANT,"Synthetic","clinic","CLINIC","HUMAN","ACTIVE",List.of()));assertEquals("MODULE_NOT_INCLUDED",assertThrows(ApiException.class,()->f.store.balance(f.request,PATIENT)).code);assertEquals(2,f.calls.size());}
 @Test void directMalformedContextUuidTokenAndMissingRequestStopBeforeSql(){safe(()->f.store.balance(null,PATIENT));f.request.setAttribute("health.tenant","bad");safe(()->f.store.balance(f.request,PATIENT));f.actor("CAJ");f.request.setAttribute("health.actor",new Actor("bad","Synthetic","synthetic@example.test",TENANT,List.of("CAJ"),"a".repeat(64)));safe(()->f.store.balance(f.request,PATIENT));f.request.setAttribute("health.actor",new Actor(ACTOR,"Synthetic","synthetic@example.test",TENANT,List.of("CAJ"),"bad"));safe(()->f.store.balance(f.request,PATIENT));f.actor("CAJ");f.request.setAttribute("health.tenant",new TenantRef(OTHER,"Foreign","foreign","CLINIC","HUMAN","ACTIVE",List.of("FINANCE")));assertEquals(403,assertThrows(ApiException.class,()->f.store.balance(f.request,PATIENT)).status);verifyNoInteractions(f.executor);}
 @Test void vendorConflictsRollbackOuterJoinAndCommitFailuresNeverRetry(){for(int vendor:List.of(51000,51001,51002,51003,51004,51005,99999)){doThrow(new RuntimeException(new java.sql.SQLException("private driver canary",null,vendor))).when(f.executor).execute(any(),any(),any(Object[].class));var e=assertThrows(ApiException.class,()->f.store.post(f.request,input(),KEY));assertEquals(vendor==51000?400:vendor==51002?404:vendor==51003||vendor==51005?409:vendor==99999?500:403,e.status);assertNull(e.getCause());assertFalse(e.toString().contains("canary"));}verify(f.executor,times(7)).execute(eq(SqlServerProcedure.FINANCE_POST),any(),any(Object[].class));}
 @Test void modeledJoinAndCommitFailureCannotReturnPostSuccess(){assertThrows(RuntimeException.class,()->f.manager.outer(()->{f.store.post(f.request,input(),KEY);assertFalse(f.manager.events.contains("commit"));throw new RuntimeException("cancel");}));assertEquals("rollback",f.manager.events.getLast());assertEquals(1,Collections.frequency(f.manager.events,"begin:0"));f.manager.failCommit=true;safe(()->f.store.post(f.request,input(),KEY));assertEquals(2,f.calls.size());}
}
